client_script:
var COUT=['cout_supports_pv','cout_supports_batteries','cout_modules_pv','cout_batteries','cout_onduleurs','cout_cables','cout_terre','cout_protection','cout_accessoires_cablage','cout_gestionnaire','frais_carburant','frais_location_camion','frais_perdiems','frais_hebergement','frais_autres'];
function gv(f){var v=frappe.web_form.get_value(f);return parseFloat(v)||0;}
function recompute(){try{var total=0;COUT.forEach(function(f){total+=gv(f);});frappe.web_form.set_value('cout_total_realisation',total);var facture=gv('montant_total_facture'),avance=gv('montant_avance_demarrage'),budget=gv('budget_previsionnel'),taxes=gv('taxes');frappe.web_form.set_value('ecart_avance',total-avance);frappe.web_form.set_value('ecart_budget_previsionnel',total-budget);var mb=facture-total;frappe.web_form.set_value('marge_brute',mb);frappe.web_form.set_value('marge_nette',mb-taxes);}catch(e){}}
frappe.web_form.after_load=function(){COUT.concat(['montant_total_facture','montant_avance_demarrage','budget_previsionnel','taxes']).forEach(function(f){try{frappe.web_form.on(f,recompute);}catch(e){}});recompute();var doc=frappe.web_form.doc;if(doc&&doc.name&&!String(doc.name).startsWith('new')){var refEl=document.createElement('div');refEl.innerHTML='<div style="margin-bottom:12px;padding:8px 16px;background:#e8f5e9;color:#2e7d32;border-left:4px solid #43a047;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">R\u00e9f. : '+doc.name+(doc.statut?'  \u2014  '+doc.statut:'')+'</div>';var w=document.querySelector('.web-form-wrapper')||document.querySelector('.container');if(w)w.prepend(refEl);}};
